import json, os, sys, market_model

def read(path, default):
    try:
        with open(path, encoding="utf-8") as f:
            return json.load(f)
    except (OSError, ValueError):
        return default

def items(value):
    if isinstance(value, list):
        return value
    if isinstance(value, dict):
        for key in ("items", "products", "catalog", "posts", "inventory", "stock"):
            if isinstance(value.get(key), list):
                return value[key]
        return [value]
    return []

def main():
    a = json.load(sys.stdin)
    md = os.environ["MARKET_DIR"]
    limit = max(1, min(100, int(a.get("limit", 20))))
    query = str(a.get("query", "")).lower()
    category = str(a.get("category", "")).lower()
    def matches(row):
        text = json.dumps(row, ensure_ascii=False, default=str).lower()
        return (not query or query in text) and (not category or category in text)
    catalog = items(read(os.path.join(md, "catalog.json"), []))
    forum = items(read(os.path.join(md, "forum.json"), []))
    inventory = read(os.path.join(md, "inventory.json"), {})
    rows = market_model.load_rows(md)
    out = {
        "catalog_count": sum(matches(x) for x in catalog),
        "catalog": [x for x in catalog if matches(x)][:limit],
        "ledger_recent": [x for x in reversed(list(rows)) if matches(x)][:limit],
        "forum_recent": [x for x in reversed(forum) if matches(x)][:limit],
        "inventory": inventory
    }
    print(json.dumps(out, ensure_ascii=False, default=str))

main()
